// Manual acceptance evidence: paste into Node started in /app/apps/api of the authorized validation container.
// Performs read-only Prisma/controller comparisons; does not validate authentication or mutate records.
(async()=>{const assert=(await import("node:assert/strict")).default;const {PrismaService}=await import("./dist/prisma/prisma.service.js");const {AdminDashboardController}=await import("./dist/admin/admin-dashboard.controller.js");const db=new PrismaService();try{const controller=new AdminDashboardController(db);const qualified=["CONFIRMED","PACKED","SHIPPED","DELIVERED","RETURN_REQUESTED","RETURNED","REFUNDED"];const evidence=[];for(const [from,to] of [["2026-09-01","2026-09-28"],["2026-09-18","2026-09-18"],["2026-09-19","2026-09-25"],["2026-09-28","2026-09-28"]]){const start=new Date(from+"T00:00:00+05:30"),end=new Date(new Date(to+"T00:00:00+05:30").getTime()+86400000),days=(end-start)/86400000,previousStart=new Date(start.getTime()-(end-start));const raw=await db.order.findMany({where:{status:{in:qualified},createdAt:{gte:previousStart,lt:end}},select:{createdAt:true,totalPaise:true}});const current=raw.filter(o=>o.createdAt>=start),previous=raw.filter(o=>o.createdAt<start);const sum=rows=>rows.reduce((n,o)=>n+o.totalPaise,0);const report=await controller.overview(from,to);assert.equal(report.metrics.salesPaise,sum(current));assert.equal(report.metrics.orders,current.length);assert.equal(report.metrics.previousSalesPaise,sum(previous));assert.equal(report.series.length,days);for(let i=0;i<days;i++){const a=new Date(start.getTime()+i*86400000),b=new Date(a.getTime()+86400000),pa=new Date(previousStart.getTime()+i*86400000),pb=new Date(pa.getTime()+86400000);const day=raw.filter(o=>o.createdAt>=a&&o.createdAt<b),prior=raw.filter(o=>o.createdAt>=pa&&o.createdAt<pb);assert.equal(report.series[i].salesPaise,sum(day));assert.equal(report.series[i].orders,day.length);assert.equal(report.series[i].previousSalesPaise,sum(prior));assert.equal(report.series[i].previousOrders,prior.length);}evidence.push({from,to,orders:current.length,salesPaise:sum(current),previousSalesPaise:sum(previous),days,pass:true});}const all=await controller.queue("orders","ALL",undefined,"1");assert.equal(all.total,await db.order.count());assert.equal(all.rows.length,Math.min(25,all.total));const second=await controller.queue("orders","ALL",undefined,"2");assert.equal(second.rows.length,Math.max(0,Math.min(25,all.total-25)));const packed=await controller.queue("orders","PACKED",undefined,"1");assert.equal(packed.total,await db.order.count({where:{status:"PACKED"}}));assert.ok(packed.rows.every(o=>o.status==="PACKED"));const deliveries=await controller.queue("deliveries","ALL",undefined,"1");assert.equal(deliveries.total,await db.order.count({where:{status:{in:["CONFIRMED","PACKED","SHIPPED"]}}}));const sample=all.rows[0];if(sample){const found=await controller.queue("orders","ALL",sample.orderNumber,"1");assert.ok(found.rows.some(o=>o.orderNumber===sample.orderNumber));}const returns=await controller.queue("returns","ALL",undefined,"1");const inventory=await db.inventory.findMany({where:{variant:{active:true,product:{status:"ACTIVE"}}},select:{onHand:true,reserved:true,safetyStock:true,reorderLevel:true}});const low=inventory.filter(i=>i.onHand-i.reserved-i.safetyStock<=i.reorderLevel).length;const summary=await controller.overview("2026-09-01","2026-09-28");assert.equal(summary.metrics.lowStock,low);console.log(JSON.stringify({type:"READ_ONLY_DATABASE_RECONCILIATION",periods:evidence,queues:{orders:all.total,page2:second.rows.length,packed:packed.total,deliveries:deliveries.total,activeReturns:returns.total},lowStock:low,staffCount:await db.adminStaff.count(),config:{bootstrapConfigured:Boolean(process.env.ADMIN_BOOTSTRAP_EMAIL),delhiveryConfigured:Boolean(process.env.DELHIVERY_API_TOKEN),razorpayTestConfigured:(process.env.RAZORPAY_KEY_ID||"").startsWith("rzp_test_")},pass:true}));}finally{await db.$disconnect();}})().catch(e=>console.error("READ_CHECK_FAILED",e.message))
